package com.tutorhub.parent.controller;
import com.tutorhub.common.security.CurrentUser; import com.tutorhub.parent.dto.*; import com.tutorhub.parent.service.ParentService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/parents/me/children") public class ParentController {private final ParentService service;private final CurrentUser current;public ParentController(ParentService s,CurrentUser c){service=s;current=c;}@GetMapping List<ChildResponse> list(){return service.children(current.require());}@PostMapping @ResponseStatus(HttpStatus.CREATED) ChildResponse create(@Valid @RequestBody ChildRequest r){return service.create(current.require(),r);}@PutMapping("/{id}") ChildResponse update(@PathVariable Long id,@Valid @RequestBody ChildRequest r){return service.update(current.require(),id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){service.delete(current.require(),id);}}
